1	package nexusfixture_test
2	
3	import (
4		"bytes"
5		"strings"
6		"testing"
7	
8		"github.com/anthnel/devdesk/internal/nexusfixture"
9	)
10	
11	// DEVDESK-580 step 5: the optional "flow" and "effect" headers and the
12	// "badcred" identity. The inputs are synthetic (see synthHeaders).
13	
14	// withHeaders inserts header lines between the "redacted" header and the request.
15	func withHeaders(lines string) string {
16		return synthHeaders + lines + synthRequest + synthResponse
17	}
18	
19	func TestFlowAndEffectConstantsAreTheWrittenValues(t *testing.T) {
20		if nexusfixture.FlowBearer != "bearer" || nexusfixture.FlowRedirects != "redirects" || nexusfixture.EffectCaches != "caches" {
21			t.Errorf("values = %q %q %q, want bearer redirects caches",
22				nexusfixture.FlowBearer, nexusfixture.FlowRedirects, nexusfixture.EffectCaches)
23		}
24		if nexusfixture.BadCredentials != "badcred" {
25			t.Errorf("BadCredentials = %q, want badcred", nexusfixture.BadCredentials)
26		}
27	}
28	
29	// Flow and effect are written after state and before record, in that order.
30	func TestParseFlowAndEffectHeadersRoundTrip(t *testing.T) {
31		tests := []struct {
32			name       string
33			lines      string
34			wantFlow   string
35			wantEffect string
36		}{
37			{"flow bearer", "# flow: bearer\n", nexusfixture.FlowBearer, ""},
38			{"flow redirects", "# flow: redirects\n", nexusfixture.FlowRedirects, ""},
39			{"effect caches", "# effect: caches\n", "", nexusfixture.EffectCaches},
40			{"flow and effect", "# flow: bearer\n# effect: caches\n", nexusfixture.FlowBearer, nexusfixture.EffectCaches},
41			{"after state, before record and recorded-by",
42				"# state: upstream-cut\n# flow: redirects\n# effect: caches\n# record: replay\n# recorded-by: nexus-bench record\n",
43				nexusfixture.FlowRedirects, nexusfixture.EffectCaches},
44			{"neither", "", "", ""},
45		}
46		for _, tt := range tests {
47			t.Run(tt.name, func(t *testing.T) {
48				data := withHeaders(tt.lines)
49				f, err := nexusfixture.Parse("synthetic", "flow--anon.http", []byte(data))
50				if err != nil {
51					t.Fatalf("Parse: %v", err)
52				}
53				if f.Meta.Flow != tt.wantFlow || f.Meta.Effect != tt.wantEffect {
54					t.Errorf("Meta.Flow, Meta.Effect = %q, %q, want %q, %q", f.Meta.Flow, f.Meta.Effect, tt.wantFlow, tt.wantEffect)
55				}
56				if got := nexusfixture.Format(f); !bytes.Equal(got, []byte(data)) {
57					t.Errorf("Format(Parse(x)) != x:\n%s\nwant:\n%s", got, data)
58				}
59			})
60		}
61	}
62	
63	// Format writes the headers a Fixture holds, wherever it came from.
64	func TestFormatWritesFlowAndEffectInPlace(t *testing.T) {
65		f, err := nexusfixture.Parse("synthetic", "built--anon.http", []byte(synthValid))
66		if err != nil {
67			t.Fatal(err)
68		}
69		f.Meta.State = "upstream-cut"
70		f.Meta.Flow = nexusfixture.FlowBearer
71		f.Meta.Effect = nexusfixture.EffectCaches
72		f.Meta.Record = "replay"
73		want := synthHeaders + "# state: upstream-cut\n# flow: bearer\n# effect: caches\n# record: replay\n" + synthRequest + synthResponse
74		if got := string(nexusfixture.Format(f)); got != want {
75			t.Errorf("Format = \n%s\nwant\n%s", got, want)
76		}
77	}
78	
79	func TestParseRefusesAnUnknownFlowOrEffectNamingTheHeader(t *testing.T) {
80		tests := []struct {
81			name   string
82			lines  string
83			header string // the header the error must name
84		}{
85			{"flow follow-all", "# flow: follow-all\n", "flow"},
86			{"flow is case sensitive", "# flow: Bearer\n", "flow"},
87			{"flow with a second word", "# flow: bearer redirects\n", "flow"},
88			{"effect deletes", "# effect: deletes\n", "effect"},
89			{"effect is case sensitive", "# effect: Caches\n", "effect"},
90			{"flow given twice", "# flow: bearer\n# flow: redirects\n", "flow"},
91		}
92		for _, tt := range tests {
93			t.Run(tt.name, func(t *testing.T) {
94				f, err := nexusfixture.Parse("synthetic", "bad--anon.http", []byte(withHeaders(tt.lines)))
95				if err == nil {
96					t.Fatalf("Parse accepted the file: %+v", f.Meta)
97				}
98				msg := err.Error()
99				if !strings.Contains(msg, "bad--anon.http") {
100					t.Errorf("error %q does not name the file", msg)
101				}
102				if !strings.Contains(strings.ToLower(msg), tt.header) {
103					t.Errorf("error %q does not name the %q header", msg, tt.header)
104				}
