106				// error must be about the header, not the unrelated "unknown header".
107				if strings.Contains(msg, `unknown header "`+tt.header+`"`) {
108					t.Errorf("error %q reads as if the %q header did not exist", msg, tt.header)
109				}
110			})
111		}
112	}
