111	func parseErr(fileName, format string, args ...any) error {
112		return fmt.Errorf("nexusfixture: %s: %s", fileName, fmt.Sprintf(format, args...))
113	}
114	
115	// Parse reads one fixture file. fileName is the base name, with ".http". A file
116	// is LF only: a carriage return anywhere is refused. A body line made of "###"
117	// preceded by any number of backslashes is read with one backslash less (Format
118	// writes it with one more), so that a body never reads as the exchange separator.
119	func Parse(campaign, fileName string, data []byte) (Fixture, error) {
120		f := Fixture{Campaign: campaign}
121		name, ok := strings.CutSuffix(fileName, fileSuffix)
122		if !ok {
123			return f, parseErr(fileName, "the file name must end in %s", fileSuffix)
124		}
125		f.Name = name
126		i := strings.LastIndex(name, identitySep)
127		if i < 0 {
128			return f, parseErr(fileName, "no identity suffix, want --admin, --pull or --anon")
129		}
130		f.Scenario, f.Identity = name[:i], Identity(name[i+len(identitySep):])
131		switch f.Identity {
132		case Admin, Pull, Anonymous:
133		default:
134			return f, parseErr(fileName, "unknown identity suffix %q, want admin, pull or anon", string(f.Identity))
135		}
136	
137		if bytes.IndexByte(data, '\r') >= 0 {
138			return f, parseErr(fileName, "the file has a carriage return (CRLF line endings): fixtures use LF only")
139		}
140	
141		meta, rest, err := parseMeta(string(data))
142		if err != nil {
143			return f, parseErr(fileName, "%v", err)
144		}
145		f.Meta = meta
146	
147		chunks := splitExchanges(rest)
148		for n, chunk := range chunks {
149			ex, err := parseExchange(chunk, meta.Record == RecordPending)
150			if err != nil {
151				if len(chunks) > 1 {
152					return f, parseErr(fileName, "exchange %d: %v", n+1, err)
153				}
154				return f, parseErr(fileName, "%v", err)
155			}
156			f.Exchanges = append(f.Exchanges, ex)
157		}
158		return f, nil
159	}
160	
161	// nextLine cuts the first line of s; ok is false when s is empty.
162	func nextLine(s string) (line, rest string, ok bool) {
163		if s == "" {
164			return "", "", false
165		}
166		line, rest, _ = strings.Cut(s, "\n")
167		return line, rest, true
168	}
169	
170	// parseMeta reads the "# key: value" lines and the blank line after them.
171	func parseMeta(text string) (Meta, string, error) {
172		raw := map[string]string{}
173		for strings.HasPrefix(text, "#") {
174			var line string
175			line, text, _ = nextLine(text)
176			body, ok := strings.CutPrefix(line, "# ")
177			if !ok {
178				return Meta{}, "", fmt.Errorf("malformed header line, want \"# key: value\"")
179			}
180			key, value, _ := strings.Cut(body, ":")
181			if !isKnownHeader(key) {
182				return Meta{}, "", fmt.Errorf("unknown header %q", key)
183			}
184			if _, dup := raw[key]; dup {
185				return Meta{}, "", fmt.Errorf("header %q given twice", key)
186			}
187			raw[key] = strings.TrimSpace(value)
188		}
189		for _, key := range requiredHeaders {
190			if raw[key] == "" {
191				return Meta{}, "", fmt.Errorf("missing %s header", key)
192			}
193		}
194		m := Meta{
195			Scenario: raw["scenario"], Measured: raw["measured"], Account: raw["account"], Redacted: raw["redacted"],
196			State: raw["state"], Record: raw["record"], RecordedBy: raw["recorded-by"],
197		}
198		if err := parseNexus(&m, raw["nexus"]); err != nil {
199			return Meta{}, "", err
200		}
201		if err := checkMeasured(m.Measured); err != nil {
202			return Meta{}, "", err
203		}
204		if err := checkRecord(m.Record); err != nil {
205			return Meta{}, "", err
206		}
207		line, rest, ok := nextLine(text)
208		if !ok || line != "" {
209			return Meta{}, "", fmt.Errorf("a blank line must separate the headers from the request")
210		}
211		return m, rest, nil
212	}
213	
214	func isKnownHeader(key string) bool {
215		for _, k := range requiredHeaders {
216			if k == key {
217				return true
218			}
219		}
220		for _, k := range optionalHeaders {
221			if k == key {
222				return true
223			}
224		}
225		return false
226	}
227	
228	// parseNexus reads "<version> <EDITION> [(free text)]".
229	func parseNexus(m *Meta, v string) error {
230		version, rest, _ := strings.Cut(v, " ")
231		edition, rest, _ := strings.Cut(strings.TrimSpace(rest), " ")
232		rest = strings.TrimSpace(rest)
233		if !versionPattern.MatchString(version) {
234			return fmt.Errorf("nexus header: %q is not a version", version)
235		}
236		if edition == "" {
237			return fmt.Errorf("nexus header: the edition is missing after the version")
238		}
239		m.NexusVersion, m.Edition = version, edition
240		if rest == "" {
241			return nil
242		}
243		inner, ok := strings.CutPrefix(rest, "(")
244		if ok {
245			inner, ok = strings.CutSuffix(inner, ")")
246		}
247		if !ok {
248			return fmt.Errorf("nexus header: the text after the edition must be in parentheses")
249		}
250		m.NexusNote = inner
251		return nil
252	}
253	
254	func checkMeasured(v string) error {
255		if len(v) < len("2006-01-02") {
256			return fmt.Errorf("measured header: %q does not start with a YYYY-MM-DD date", v)
257		}
258		if _, err := time.Parse("2006-01-02", v[:10]); err != nil {
259			return fmt.Errorf("measured header: does not start with a YYYY-MM-DD date")
260		}
261		if after := v[10:]; after != "" && !strings.HasPrefix(after, ",") {
262			return fmt.Errorf("measured header: the date may only be followed by \", free text\"")
263		}
264		return nil
265	}
266	
267	func checkRecord(v string) error {
268		if reason, ok := strings.CutPrefix(v, "skip: "); ok && strings.TrimSpace(reason) != "" {
269			return nil
270		}
271		if v == "" || v == "replay" || v == RecordPending {
272			return nil
273		}
274		return fmt.Errorf("record header: %q is not replay, pending or skip: <reason>", v)
275	}
276	
277	// splitExchanges cuts the text after the header at each "###" line.
278	func splitExchanges(text string) []string {
279		parts := strings.Split(text, "\n"+exchangeSep+"\n")
280		for i := 0; i < len(parts)-1; i++ {
281			parts[i] += "\n" // the line break the separator consumed
282		}
283		return parts
284	}
285	
286	func parseExchange(text string, pending bool) (Exchange, error) {
287		var ex Exchange
288		line, text, _ := nextLine(text)
289		fields := strings.Fields(line)
290		if len(fields) != 3 || fields[2] != httpVersion {
291			return ex, fmt.Errorf("request line must be \"METHOD target %s\"", httpVersion)
292		}
293		ex.Method, ex.Target = fields[0], fields[1]
294	
295		header, text, blank, err := readHeaders(text)
296		if err != nil {
297			return ex, fmt.Errorf("request: %w", err)
298		}
299		ex.Host = header.Get("Host")
300		header.Del("Host")
301		ex.RequestHeader = header
302		if ex.Host == "" {
303			return ex, fmt.Errorf("the request has no Host header")
304		}
305	
306		if !blank || text == "" {
307			if pending {
308				return ex, nil
309			}
310			return ex, fmt.Errorf("the response is missing (only a pending fixture may hold a request alone)")
311		}
312		if pending {
313			return ex, fmt.Errorf("a pending fixture must not carry a response")
314		}
315		return ex, parseResponse(&ex, text)
316	}
317	
318	func parseResponse(ex *Exchange, text string) error {
319		line, text, _ := nextLine(text)
320		rest, ok := strings.CutPrefix(line, httpVersion+" ")
321		if !ok {
322			return fmt.Errorf("status line must be \"%s <code> <reason>\"", httpVersion)
323		}
324		code, reason, _ := strings.Cut(rest, " ")
325		status, err := strconv.Atoi(code)
326		if err != nil || status < 100 || status > 599 {
327			return fmt.Errorf("status code is not a number from 100 to 599")
328		}
329		// Format trims the status line, so a blank or padded phrase cannot round-trip.
330		ex.Status, ex.Reason = status, strings.TrimSpace(reason)
331	
332		header, text, blank, err := readHeaders(text)
333		if err != nil {
334			return fmt.Errorf("response: %w", err)
335		}
336		if !blank {
337			return fmt.Errorf("a blank line must separate the response headers from the body")
338		}
339		ex.Header = header
340	
341		body := strings.TrimSuffix(text, "\n")
342		if body == stubEmpty || isOmittedStub(body) {
343			ex.Stub = body
344		} else {
345			ex.Body = []byte(unescapeBody(body))
346		}
347		return nil
348	}
349	
350	// isOmittedStub reports whether a body is one of the two summaries Redact writes
351	// in place of a body: "<HTML body omitted: ...>" or "<body omitted: ...>".
352	func isOmittedStub(body string) bool {
353		return (strings.HasPrefix(body, stubHTMLStart) || strings.HasPrefix(body, stubOmittedStart)) && strings.HasSuffix(body, ">")
354	}
355	
356	// isSeparatorLike reports whether a body line is "###" preceded by any number
357	// of backslashes: the lines Format escapes and Parse unescapes.
358	func isSeparatorLike(line string) bool {
359		return strings.HasSuffix(line, exchangeSep) && strings.Trim(line[:len(line)-len(exchangeSep)], `\`) == ""
360	}
361	
362	// mapSeparatorLikeLines applies fn to each body line that isSeparatorLike.
363	func mapSeparatorLikeLines(body string, fn func(string) string) string {
364		lines := strings.Split(body, "\n")
365		for i, l := range lines {
366			if isSeparatorLike(l) {
367				lines[i] = fn(l)
368			}
369		}
370		return strings.Join(lines, "\n")
371	}
372	
373	func escapeBody(body []byte) []byte {
374		return []byte(mapSeparatorLikeLines(string(body), func(l string) string { return `\` + l }))
375	}
376	
377	func unescapeBody(body string) string {
378		return mapSeparatorLikeLines(body, func(l string) string { return l[1:] })
379	}
380	
381	// readHeaders reads "Name: value" lines up to a blank line. blank is false when
382	// the text ended first.
383	func readHeaders(text string) (h http.Header, rest string, blank bool, err error) {
384		h = http.Header{}
385		for {
386			var line string
387			var ok bool
388			line, text, ok = nextLine(text)
389			switch {
390			case !ok:
391				return h, "", false, nil
392			case line == "":
393				return h, text, true, nil
394			case strings.HasPrefix(line, "HTTP/"):
395				return nil, "", false, fmt.Errorf("a blank line must separate the request from the response")
396			}
397			name, value, found := strings.Cut(line, ":")
398			if !found || name == "" {
399				return nil, "", false, fmt.Errorf("malformed header line, want \"Name: value\"")
400			}
401			h.Add(textproto.CanonicalMIMEHeaderKey(name), strings.TrimPrefix(value, " "))
402		}
403	}
404	
405	// Format writes a fixture in the file format; Format(Parse(b)) == b for a file
406	// the recorder or the NX-03 import wrote.
407	func Format(f Fixture) []byte {
408		var b bytes.Buffer
409		writeMeta(&b, f.Meta)
410		for i, ex := range f.Exchanges {
411			if i == 0 {
412				b.WriteString("\n")
413			} else {
414				b.WriteString(exchangeSep + "\n")
415			}
416			writeExchange(&b, ex)
417		}
418		return b.Bytes()
419	}
420	
421	func writeMeta(b *bytes.Buffer, m Meta) {
422		nexus := m.NexusVersion + " " + m.Edition
423		if m.NexusNote != "" {
424			nexus += " (" + m.NexusNote + ")"
425		}
426		lines := []struct{ key, value string }{
427			{"scenario", m.Scenario}, {"nexus", nexus}, {"measured", m.Measured},
428			{"account", m.Account}, {"redacted", m.Redacted},
429		}
430		for _, l := range lines {
431			fmt.Fprintf(b, "# %s: %s\n", l.key, l.value)
432		}
433		for _, l := range []struct{ key, value string }{{"state", m.State}, {"record", m.Record}, {"recorded-by", m.RecordedBy}} {
434			if l.value != "" {
435				fmt.Fprintf(b, "# %s: %s\n", l.key, l.value)
436			}
437		}
438	}
439	
440	func writeExchange(b *bytes.Buffer, ex Exchange) {
441		fmt.Fprintf(b, "%s %s %s\nHost: %s\n", ex.Method, ex.Target, httpVersion, ex.Host)
442		writeHeaders(b, ex.RequestHeader, requestOrder, "Host")
443		if ex.Status == 0 {
444			return
445		}
446		reason := ex.Reason
447		if reason == "" {
448			reason = http.StatusText(ex.Status)
449		}
450		b.WriteString("\n" + strings.TrimSpace(fmt.Sprintf("%s %d %s", httpVersion, ex.Status, reason)) + "\n")
451		writeHeaders(b, ex.Header, responseOrder)
452		b.WriteString("\n")
453		if ex.Stub != "" {
454			b.WriteString(ex.Stub)
455		} else {
456			b.Write(escapeBody(ex.Body))
457		}
458		b.WriteString("\n")
459	}
460	
461	// writeHeaders writes the headers in a fixed order (the preferred names first,
462	// then the others sorted) so that a regeneration does not reshuffle a file.
463	func writeHeaders(b *bytes.Buffer, h http.Header, preferred []string, skip ...string) {
464		skipped := map[string]bool{}
465		for _, s := range skip {
466			skipped[s] = true
467		}
468		var names []string
469		for _, p := range preferred {
470			if _, ok := h[p]; ok && !skipped[p] {
471				names = append(names, p)
472			}
473		}
474		var others []string
475		for k := range h {
476			if skipped[k] || contains(preferred, k) {
477				continue
478			}
479			others = append(others, k)
480		}
481		sort.Strings(others)
482		for _, name := range append(names, others...) {
483			display := name
484			if d, ok := displayNames[name]; ok {
485				display = d
486			}
487			for _, v := range h[name] {
488				fmt.Fprintf(b, "%s: %s\n", display, v)
489			}
490		}
491	}
492	
493	func contains(list []string, s string) bool {
494		for _, v := range list {
495			if v == s {
496				return true
497			}
498		}
499		return false
500	}
