29		ruleAuthorization  = "authorization-not-redacted"
30		ruleSession        = "cookie-or-session"
31		ruleHeaderAllowed  = "response-header-outside-allowlist"
32		ruleRequestHeader  = "request-header-outside-allowlist"
33		ruleMalformed      = "malformed-header-line"
34		ruleJWT            = "jwt-like-value"
35		ruleSecretFormat   = "secret-token-format"
36		ruleJSONSecret     = "REDACTED"
37		ruleHost           = "host-not-allowed"
38		rulePrivateAddress = "private-or-link-local-address"
39		ruleInternalName   = "internal-name-or-path"
40		ruleQuery          = "request-query-outside-allowlist"
41		ruleExactTerm      = "exact-term"
42	)
43	
44	// sessionKV is the name of the Nexus session cookie, refused anywhere in a fixture.
45	const sessionKV = "NXSESSIONID"
46	
47	var (
48		jwtLike = regexp.MustCompile(`eyJ[A-Za-z0-9_-]{10,}`)
49		// secretFormat matches well-known secret formats: GitHub and GitLab tokens,
50		// AWS access key ids, and the first line of a PEM private key.
51		secretFormat = regexp.MustCompile(
52			`gh[pousr]_[A-Za-z0-9]{36,}|glpat-[A-Za-z0-9_-]{20,}|(?:AKIA|ASIA)[0-9A-Z]{16}|-----BEGIN [A-Z ]*PRIVATE KEY-----`)
53		// urlAuth reads the authority of a URL, also when its slashes are JSON-escaped.
54		urlAuth = regexp.MustCompile(`(?i)https?:\\?/\\?/([^\s/"'<>?#\\,;)]+)`)
55		// ipv4Like needs a non-numeric character before the address, not a word boundary:
56		// "ip10.1.2.3" holds one.
57		ipv4Like = regexp.MustCompile(`(?:^|[^0-9])(\d{1,3}(?:\.\d{1,3}){3})`)
58		// ipv6Local starts a unique-local (fc00::/7) or link-local (fe80::/10) address.
59		ipv6Local = regexp.MustCompile(`(?i)(?:^|[^0-9a-f])(?:f[cd][0-9a-f]{2}|fe[89ab][0-9a-f]):`)
60		// bareHost is a host name in an internal zone; the group is the name.
61		bareHost = regexp.MustCompile(`(?i)([a-z0-9_-]+(?:\.[a-z0-9_-]+)*\.(?:home\.arpa|lan|internal|local))(?:$|[^a-z0-9_-])`)
62		// localPath is a user's home directory anchored at the start of a value (after
63		// a quote, a blank or "="): "/home/" inside an image path is legitimate.
64		// winProfile is a Windows profile path, raw or JSON-escaped.
65		localPath  = regexp.MustCompile(`(?:^|["\s=])/(?:root|home|Users)/`)
66		winProfile = regexp.MustCompile(`(?i)[a-z]:\\+users`)
67	
68		cgnat = netip.MustParsePrefix("100.64.0.0/10")
69	
70		sessionHeaders = []string{"cookie", "set-cookie", "x-nexus-ui"}
71		// internalNames are matched ignoring case.
72		internalNames = []string{"datomir", "secrets.json", "xdg_state_home"}
73		// queryParams are the only parameters a request URL may carry (the paging of _catalog).
74		queryParams = []string{"n", "last"}
75		// jsonEscaper writes a term as it sits inside a JSON string.
76		jsonEscaper = strings.NewReplacer(`\`, `\\`, `"`, `\"`, `/`, `\/`)
77	)
78	
79	// lineState is where a line sits in the file: the commented header, or one of
80	// the parts of an exchange.
81	type lineState int
82	
83	const (
84		stMeta lineState = iota
85		stReqLine
86		stReqHeaders
87		stRespLine
88		stRespHeaders
89		stBody
90	)
91	
92	// CheckLeaks scans one fixture, line by line (lines count from 1), for what a
93	// fixture must not hold: an Authorization other than the placeholders, a cookie
94	// or session header, a request header outside Host, Authorization and Accept, a
95	// response header outside ResponseHeaderAllowlist, a line of a header section
96	// that is not "Name: value", a request query parameter other than n and last, a
97	// JWT-like value or another well-known secret format, a JSON secret key whose
98	// value is not "<redacted>" (or null), a host outside AllowedHosts, a private,
99	// link-local, CGNAT or unique-local address, an internal name or local path, and
100	// each term of exact (recorder passwords and their Basic encodings, or an
101	// external deny list), also in another case, JSON-escaped or URL-escaped; an
102	// empty term matches nothing. The text is scanned as written, not parsed: a file
103	// that does not parse is still checked.
104	func CheckLeaks(fixture string, data []byte, exact []string) []Leak {
105		c := &leakScan{fixture: fixture, seen: map[leakKey]bool{}, exact: exactVariants(exact)}
106		text := string(data)
107		state := stMeta
108		for i, line := range strings.Split(text, "\n") {
109			state = c.scanLine(i+1, line, state)
110		}
111		c.scanJSONSecrets(text)
112		sort.SliceStable(c.leaks, func(i, j int) bool { return c.leaks[i].Line < c.leaks[j].Line })
113		return c.leaks
114	}
115	
116	// exactVariants lists, lower-cased, the forms of each term that can sit in a
117	// fixture: as given, JSON-escaped, URL-escaped as a query value and as a path.
118	func exactVariants(terms []string) []string {
119		var out []string
120		for _, term := range terms {
121			if term == "" {
122				continue
123			}
124			for _, v := range []string{term, jsonEscaper.Replace(term), url.QueryEscape(term), url.PathEscape(term)} {
125				out = append(out, strings.ToLower(v))
126			}
127		}
128		return out
129	}
130	
131	type leakKey struct {
132		line int
133		rule string
134	}
135	
136	type leakScan struct {
137		fixture string
138		exact   []string // lower-cased variants of the exact terms
139		leaks   []Leak
140		seen    map[leakKey]bool
141	}
142	
143	// add records a rule once per line.
144	func (c *leakScan) add(line int, rule string) {
145		k := leakKey{line, rule}
146		if c.seen[k] {
147			return
148		}
149		c.seen[k] = true
150		c.leaks = append(c.leaks, Leak{Fixture: c.fixture, Line: line, Rule: rule})
151	}
152	
153	// scanLine checks one line and returns the state of the next.
154	func (c *leakScan) scanLine(n int, line string, state lineState) lineState {
155		if line == exchangeSep && state != stMeta {
156			return stReqLine
157		}
158		switch state {
159		case stReqLine:
160			c.scanRequestLine(n, line)
161		case stReqHeaders, stRespHeaders:
162			c.scanHeader(n, line, state)
163		}
164		c.scanText(n, line)
165		return nextState(state, line)
166	}
167	
168	func nextState(state lineState, line string) lineState {
169		switch state {
170		case stMeta:
171			if line == "" {
172				return stReqLine
173			}
174		case stReqLine:
175			return stReqHeaders
176		case stReqHeaders:
177			if line == "" {
178				return stRespLine
179			}
180		case stRespLine:
181			return stRespHeaders
182		case stRespHeaders:
183			if line == "" {
184				return stBody
185			}
186		}
187		return state
188	}
189	
190	// scanRequestLine checks the query of "METHOD target HTTP/1.1".
191	func (c *leakScan) scanRequestLine(n int, line string) {
192		fields := strings.Fields(line)
193		if len(fields) < 2 {
194			return
195		}
196		_, query, _ := strings.Cut(fields[1], "?")
197		for param := range strings.SplitSeq(query, "&") {
198			if name, _, _ := strings.Cut(param, "="); param != "" && !contains(queryParams, name) {
199				c.add(n, ruleQuery)
200			}
201		}
202	}
203	
204	func (c *leakScan) scanHeader(n int, line string, state lineState) {
205		if line == "" {
206			return
207		}
208		name, value, ok := strings.Cut(line, ":")
209		name, value = strings.TrimSpace(name), strings.TrimSpace(value)
210		if !ok || name == "" {
211			c.add(n, ruleMalformed)
212			return
213		}
214		lower := strings.ToLower(name)
215		switch {
216		case lower == "authorization" && value != authBasicRedacted && value != authBearerRedacted:
217			c.add(n, ruleAuthorization)
218		case contains(sessionHeaders, lower):
219			c.add(n, ruleSession)
220		}
221		if state == stRespHeaders && !allowedResponseHeader(name) {
222			c.add(n, ruleHeaderAllowed)
223		}
224		if state == stReqHeaders && !allowedRequestHeader(name) {
225			c.add(n, ruleRequestHeader)
226		}
227		if state == stReqHeaders && lower == "host" && !allowedHost(value) {
228			c.add(n, ruleHost)
229		}
230	}
231	
232	func allowedResponseHeader(name string) bool {
233		return allowedHeader(ResponseHeaderAllowlist, name)
234	}
235	
236	// allowedRequestHeader admits Host, Authorization and what Redact keeps of a request.
237	func allowedRequestHeader(name string) bool {
238		return allowedHeader([]string{"Host", "Authorization"}, name) || allowedHeader(requestHeaderAllowlist, name)
239	}
240	
241	func allowedHeader(allowlist []string, name string) bool {
242		canonical := http.CanonicalHeaderKey(name)
243		for _, a := range allowlist {
244			if http.CanonicalHeaderKey(a) == canonical {
245				return true
246			}
247		}
248		return false
249	}
250	
251	// scanText applies the rules that hold on any line, header or body.
252	func (c *leakScan) scanText(n int, line string) {
253		lower := strings.ToLower(line)
254		if strings.Contains(lower, strings.ToLower(sessionKV)) {
255			c.add(n, ruleSession)
256		}
257		if jwtLike.MatchString(line) {
258			c.add(n, ruleJWT)
259		}
260		if secretFormat.MatchString(line) {
261			c.add(n, ruleSecretFormat)
262		}
263		if strings.Contains(lower, "http") {
264			for _, m := range urlAuth.FindAllStringSubmatch(line, -1) {
265				if !allowedAuthority(m[1]) {
266					c.add(n, ruleHost)
267				}
268			}
269		}
270		c.scanAddresses(n, line)
271		c.scanInternal(n, line, lower)
272		for _, term := range c.exact {
273			if strings.Contains(lower, term) {
274				c.add(n, ruleExactTerm)
275			}
276		}
277	}
278	
279	// scanAddresses reports private, link-local, CGNAT and unique-local addresses.
280	func (c *leakScan) scanAddresses(n int, line string) {
281		// The cheap tests keep the regular expressions off the lines that cannot match.
282		if strings.Contains(line, ".") {
283			for _, m := range ipv4Like.FindAllStringSubmatch(line, -1) {
284				if addr, err := netip.ParseAddr(m[1]); err == nil && (addr.IsPrivate() || addr.IsLinkLocalUnicast() || cgnat.Contains(addr)) {
285					c.add(n, rulePrivateAddress)
286				}
287			}
288		}
289		if strings.Count(line, ":") > 1 && ipv6Local.MatchString(line) {
290			c.add(n, rulePrivateAddress)
291		}
292	}
293	
294	// scanInternal reports internal names, bare internal host names and local paths.
295	func (c *leakScan) scanInternal(n int, line, lower string) {
296		for _, name := range internalNames {
297			if strings.Contains(lower, name) {
298				c.add(n, ruleInternalName)
299			}
300		}
301		if strings.Contains(line, ".") {
302			for _, m := range bareHost.FindAllStringSubmatch(line, -1) {
303				if !contains(AllowedHosts, strings.ToLower(m[1])) {
304					c.add(n, ruleInternalName)
305				}
306			}
307		}
308		if (strings.Contains(line, "/") && localPath.MatchString(line)) || (strings.Contains(line, `\`) && winProfile.MatchString(line)) {
309			c.add(n, ruleInternalName)
310		}
311	}
312	
313	// scanJSONSecrets runs over the whole text, not line by line, because Redact
314	// replaces a secret value wherever it sits relative to its key. The leak is
315	// reported at the line of the key; lines are counted from where the previous key
316	// was, so the scan stays linear.
317	func (c *leakScan) scanJSONSecrets(text string) {
318		line, counted := 1, 0
319		for from := 0; ; {
320			key, value, ok := nextSecretKey(text, from, true)
321			if !ok {
322				return
323			}
324			line += strings.Count(text[counted:key], "\n")
325			counted = key
326			if keptValueLen(text[value:]) == 0 {
327				c.add(line, ruleJSONSecret)
328			}
329			from = value
330		}
331	}
332	
333	// allowedAuthority checks the authority of a URL: no user info, and a host in
334	// AllowedHosts.
335	func allowedAuthority(authority string) bool {
336		if strings.Contains(authority, "@") {
337			return false
338		}
339		return allowedHost(authority)
340	}
341	
342	// allowedHost checks a host with or without a port.
343	func allowedHost(hostPort string) bool {
344		host := hostPort
345		if h, _, err := net.SplitHostPort(hostPort); err == nil {
346			host = h
347		}
348		host = strings.Trim(strings.ToLower(host), "[]")
349		return contains(AllowedHosts, host)
350	}
