176	// isSecretKey reports whether a JSON key, as written between its quotes, names a
177	// secret. Escapes are decoded first, so "pass\u0077ord" is "password".
178	func isSecretKey(raw string) bool {
179		if strings.Contains(raw, `\`) {
180			var key string
181			if json.Unmarshal([]byte(`"`+raw+`"`), &key) == nil {
182				raw = key
183			} else {
184				raw = strings.ReplaceAll(raw, `\`, "")
185			}
186		}
187		lower := strings.ToLower(raw)
188		for _, suffix := range secretKeySuffixes {
189			if strings.HasSuffix(lower, suffix) {
190				return true
191			}
192		}
193		return false
194	}
195	
196	const jsonBlanks = " \t\r\n"
197	
198	func skipBlanks(text string, i int) int {
199		for i < len(text) && strings.IndexByte(jsonBlanks, text[i]) >= 0 {
200			i++
201		}
202		return i
203	}
204	
205	// stringEnd returns the index just after the string that opens at start, and
206	// whether it was closed. An unclosed string ends at the end of the text, or, with
207	// lineBound, at the first line break: a JSON string never holds one, and a scan
208	// of a whole fixture file must not let a stray quote shift every later pairing.
209	func stringEnd(text string, start int, lineBound bool) (int, bool) {
210		for i := start + 1; i < len(text); i++ {
211			switch text[i] {
212			case '\\':
213				if !lineBound || i+1 >= len(text) || text[i+1] != '\n' {
214					i++ // the escaped character
215				}
216			case '"':
217				return i + 1, true
218			case '\n':
219				if lineBound {
220					return i, false
221				}
222			}
223		}
224		return len(text), false
225	}
226	
227	// nextSecretKey finds the first member at or after from whose key names a
228	// secret. It returns where the key starts and where its value starts (after the
229	// colon and the blanks).
230	func nextSecretKey(text string, from int, lineBound bool) (key, value int, ok bool) {
231		for i := from; i < len(text); {
232			q := strings.IndexByte(text[i:], '"')
233			if q < 0 {
234				break
235			}
236			start := i + q
237			end, closed := stringEnd(text, start, lineBound)
238			i = end
239			if !closed {
240				continue
241			}
242			if colon := skipBlanks(text, end); colon < len(text) && text[colon] == ':' && isSecretKey(text[start+1:end-1]) {
243				return start, skipBlanks(text, colon+1), true
244			}
245		}
246		return 0, 0, false
247	}
248	
249	// valueEnd returns the index just after the JSON value that starts at start: a
250	// string, an object or array up to its matching bracket (strings skipped), or a
251	// bare number or literal. A value cut short ends at the end of the text.
252	func valueEnd(text string, start int) int {
253		if start >= len(text) {
254			return start
255		}
256		switch text[start] {
257		case '"':
258			end, _ := stringEnd(text, start, false)
259			return end
260		case '{', '[':
261			depth := 0
262			for i := start; i < len(text); i++ {
263				switch text[i] {
264				case '"':
265					end, _ := stringEnd(text, i, false)
266					i = end - 1
267				case '{', '[':
268					depth++
269				case '}', ']':
270					if depth--; depth == 0 {
271						return i + 1
272					}
273				}
274			}
275			return len(text)
276		}
277		i := start
278		for i < len(text) && strings.IndexByte(",}]"+jsonBlanks, text[i]) < 0 {
279			i++
280		}
281		return i
282	}
283	
284	// keptValueLen is the length of the value at the start of rest when it holds no
285	// secret, "<redacted>" or null, and 0 for any other value.
286	func keptValueLen(rest string) int {
287		const placeholder = `"` + redacted + `"`
288		switch {
289		case strings.HasPrefix(rest, placeholder):
290			return len(placeholder)
291		case strings.HasPrefix(rest, "null") && (len(rest) == 4 || strings.IndexByte(",}]"+jsonBlanks, rest[4]) >= 0):
292			return 4
293		}
294		return 0
295	}
