1	// Package fakenexus replays recorded Nexus answers over loopback HTTP. It is the
2	// only package of the fixture tree that imports testing: the recorder and the
3	// nexus-bench binary stay free of it (nexusfixture itself must not import it).
4	// Import it from _test.go files only.
5	package fakenexus
6	
7	import (
8		"encoding/json"
9		"net/http"
10		"net/http/httptest"
11		"net/url"
12		"regexp"
13		"strconv"
14		"strings"
15		"sync"
16		"testing"
17	
18		"github.com/anthnel/devdesk/internal/nexusfixture"
19	)
20	
21	// Password is the password the fake accepts for every account.
22	const Password = "REDACTED"
23	
24	// BadPassword is the public wrong password that, with the user "admin", makes the
25	// fake answer as the BadCredentials identity (SKELETON: not recognized yet).
26	const BadPassword = "REDACTED"
27	
28	// User returns the user name an identity authenticates as; anonymous has none.
29	func User(id nexusfixture.Identity) string {
30		switch id {
31		case nexusfixture.Admin:
32			return "admin"
33		case nexusfixture.Pull:
34			return "bench-pull"
35		default:
36			return ""
37		}
38	}
39	
40	// unknownCredentials names the identity of a request whose credentials are not
41	// one of the bench's accounts (wrong password, unknown user, Bearer...).
42	const unknownCredentials = "unrecognized credentials"
43	
44	// route is one recorded exchange, with the fixture it comes from.
45	type route struct {
46		fixture  string
47		identity nexusfixture.Identity
48		ex       nexusfixture.Exchange
49	}
50	
51	// Server answers the recorded exchanges, one httptest server per recorded Host.
52	type Server struct {
53		t testing.TB
54	
55		mu       sync.Mutex // guards hits and the fields set by New
56		hits     map[string]int
57		urls     map[string]string // recorded Host -> fake server URL
58		servers  []*httptest.Server
59		rewriter *strings.Replacer
60	}
61	
62	// New starts one loopback server for each Host the fixtures were recorded on and
63	// closes them with t. A request no fixture answers gets a 501 and a t.Errorf
64	// (never a Fatalf: the handler does not run on the test goroutine).
65	func New(t testing.TB, fixtures ...nexusfixture.Fixture) *Server {
66		t.Helper()
67		s := &Server{t: t, hits: map[string]int{}, urls: map[string]string{}}
68	
69		routes := map[string][]route{}
70		seen := map[exchangeKey]string{} // exchange -> the fixture that recorded it
71		var hosts []string
72		for _, f := range fixtures {
73			for _, ex := range f.Exchanges {
74				if _, ok := routes[ex.Host]; !ok {
75					hosts = append(hosts, ex.Host)
76					routes[ex.Host] = nil
77				}
78				if !s.accept(f, ex, seen) {
79					continue
80				}
81				routes[ex.Host] = append(routes[ex.Host], route{fixture: f.Name, identity: f.Identity, ex: ex})
82			}
83		}
84	
85		s.mu.Lock()
86		defer s.mu.Unlock()
87		var pairs []string
88		for _, host := range hosts {
89			srv := httptest.NewServer(s.handler(routes[host]))
90			s.servers = append(s.servers, srv)
91			s.urls[host] = srv.URL
92			pairs = append(pairs, "http://"+host, srv.URL)
93		}
94		s.rewriter = strings.NewReplacer(pairs...)
95		t.Cleanup(func() {
96			for _, srv := range s.servers {
97				srv.Close()
98			}
99		})
100		return s
101	}
102	
103	// exchangeKey is what a request is matched on: two exchanges sharing it cannot
104	// both be replayed.
105	type exchangeKey struct {
106		host, method, target string
107		identity             nexusfixture.Identity
108	}
109	
110	// accept reports whether an exchange can be replayed faithfully, and fails the
111	// test (naming the fixture) when it cannot: a Status of 0 (the handler would
112	// panic on it), a stub with no faithful stand-in, or a second exchange for the
113	// same host, method, target and identity. A refused exchange is not served.
114	func (s *Server) accept(f nexusfixture.Fixture, ex nexusfixture.Exchange, seen map[exchangeKey]string) bool {
115		ok := true
116		if ex.Status == 0 {
117			s.t.Errorf("fakenexus: fixture %s: %s %s on %s has no status", f.Name, ex.Method, ex.Target, ex.Host)
118			ok = false
119		}
120		if _, valid := bodyOf(ex); !valid {
121			s.t.Errorf("fakenexus: fixture %s: %s %s: stub %q has no faithful stand-in (only %q and an HTML summary with a title do)",
122				f.Name, ex.Method, ex.Target, ex.Stub, emptyStub)
123			ok = false
124		}
125		key := exchangeKey{host: ex.Host, method: ex.Method, target: ex.Target, identity: f.Identity}
126		if first, dup := seen[key]; dup {
127			s.t.Errorf("fakenexus: fixtures %s and %s both record %s %s on %s as %s",
128				first, f.Name, ex.Method, ex.Target, ex.Host, f.Identity)
129			ok = false
130		} else {
131			seen[key] = f.Name
132		}
133		return ok
134	}
135	
136	// URL returns the base URL of the fake server standing for a recorded Host,
137	// such as "127.0.0.1:30481".
138	func (s *Server) URL(recordedHost string) string {
139		s.mu.Lock()
140		defer s.mu.Unlock()
141		u, ok := s.urls[recordedHost]
142		if !ok {
143			s.t.Errorf("fakenexus: no fixture was recorded on host %s", recordedHost)
144		}
145		return u
146	}
147	
148	// Hits counts the requests the named fixture answered, tolerated ones included.
149	func (s *Server) Hits(fixtureName string) int {
150		s.mu.Lock()
151		defer s.mu.Unlock()
152		return s.hits[fixtureName]
153	}
154	
155	func (s *Server) handler(routes []route) http.Handler {
156		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
157			id, known := identify(r)
158			if known {
159				if rt, ok := match(routes, r.Method, r.URL.RequestURI(), id); ok {
160					s.replay(w, rt)
161					return
162				}
163			}
164			label := unknownCredentials
165			if known {
166				label = string(id)
167			}
168			s.t.Errorf("no recorded answer for %s %s as %s", r.Method, r.URL.RequestURI(), label)
169			http.Error(w, "no recorded answer", http.StatusNotImplemented)
170		})
171	}
172	
173	// identify reads the account a request authenticates as. known is false when the
174	// credentials are none of the bench's: that never matches a recording.
175	func identify(r *http.Request) (id nexusfixture.Identity, known bool) {
176		if r.Header.Get("Authorization") == "" {
177			return nexusfixture.Anonymous, true
178		}
179		user, pass, ok := r.BasicAuth()
180		if !ok || pass != Password {
181			return "", false
182		}
183		for _, id := range []nexusfixture.Identity{nexusfixture.Admin, nexusfixture.Pull} {
184			if user == User(id) {
185				return id, true
186			}
187		}
188		return "", false
189	}
190	
191	// match picks the exchange recorded for the method, target and identity: the
192	// exact target first, then the catalog tolerance.
193	func match(routes []route, method, target string, id nexusfixture.Identity) (route, bool) {
194		for _, rt := range routes {
195			if rt.identity == id && rt.ex.Method == method && rt.ex.Target == target {
196				return rt, true
197			}
198		}
199		if method != http.MethodGet {
200			return route{}, false
201		}
202		return matchCatalogTolerance(routes, target, id)
203	}
204	
205	// toleratedN is the only n (what DevDesk asks) tolerated without "last".
206	const toleratedN = 1000
207	
208	// matchCatalogTolerance lets "GET P?n=1000" (no "last") be answered by a fixture
209	// recorded as "GET P" without a query, provided that answer is a 200 with no Link
210	// and lists at most 1000 names: one page holds the whole catalog, as with n=1000.
211	// Any other n is not measured and is not tolerated.
212	//
213	// Measured: n=1000 and no n answer identically on the group connector
214	// (page-group-n1000--admin and catalog-group-connector-30482--admin), and, since
215	// DEVDESK-580, on the hosted and proxy catalogs by path and on the 404 of the root
216	// and of the group path (catalog-*-n1000--*, for the three identities); all pinned
217	// by TestTheCatalogToleranceHasMeasuredGround. Those exact fixtures win over the
218	// tolerance. For the other targets (the "/repository/<name>/v2/" paths, the group
219	// connector's pull and anonymous identities) it stays an inference: only no-n and
220	// n=2 were measured there. A 404 is never tolerated, so "?n=1000" on a target with
221	// no exact fixture stays unmatched.
222	func matchCatalogTolerance(routes []route, target string, id nexusfixture.Identity) (route, bool) {
223		path, rawQuery, _ := strings.Cut(target, "?")
224		query, err := url.ParseQuery(rawQuery)
225		if err != nil || len(query) != 1 || len(query["n"]) != 1 {
226			return route{}, false
227		}
228		n, err := strconv.Atoi(query.Get("n"))
229		if err != nil || n != toleratedN {
230			return route{}, false
231		}
232		for _, rt := range routes {
233			ex := rt.ex
234			if rt.identity != id || ex.Method != http.MethodGet || ex.Target != path ||
235				ex.Status != http.StatusOK || ex.Header.Get("Link") != "" {
236				continue
237			}
238			var catalog struct {
239				Repositories []string `json:"repositories"`
240			}
241			if json.Unmarshal(ex.Body, &catalog) == nil && catalog.Repositories != nil && len(catalog.Repositories) <= n {
242				return rt, true
243			}
244		}
245		return route{}, false
246	}
247	
248	// rewrittenHeaders carry an address of the recorded host; they are pointed at the
249	// fake server of that host. A body is data and is never rewritten.
250	var rewrittenHeaders = []string{"Link", "Location", "Www-Authenticate"}
251	
252	// replay writes the recorded status, headers and body. Content-Length is never
253	// copied: it is recomputed from the body actually served, since a stub is shorter
254	// than the answer it summarises.
255	func (s *Server) replay(w http.ResponseWriter, rt route) {
256		s.mu.Lock()
257		s.hits[rt.fixture]++
258		rewriter := s.rewriter
259		s.mu.Unlock()
260	
261		ex := rt.ex
262		h := w.Header()
263		for name, values := range ex.Header {
264			if name == "Content-Length" {
265				continue
266			}
267			rewrite := contains(rewrittenHeaders, name)
268			for _, v := range values {
269				if rewrite {
270					v = rewriter.Replace(v)
271				}
272				h.Add(name, v)
273			}
274		}
275		if len(ex.Header.Values("Content-Type")) == 0 {
276			h["Content-Type"] = nil // a nil value stops Go from sniffing one
277		}
278		body, _ := bodyOf(ex) // a stub without a stand-in was refused by New
279		h.Set("Content-Length", strconv.Itoa(len(body)))
280		w.WriteHeader(ex.Status)
281		_, _ = w.Write(body)
282	}
283	
284	var htmlTitle = regexp.MustCompile(`, (<title>.*</title>)>$`)
285	
286	// emptyStub is the stub of a recorded empty body.
287	const emptyStub = "<empty body>"
288	
289	// bodyOf is the body to serve: the recorded one, or a stand-in for a summarised
290	// body. Only two stubs have a faithful one: an empty body and an HTML page that
291	// kept its title. valid is false for any other stub.
292	func bodyOf(ex nexusfixture.Exchange) (body []byte, valid bool) {
293		switch {
294		case ex.Stub == "":
295			return ex.Body, true
296		case ex.Stub == emptyStub:
297			return nil, true
298		case strings.HasPrefix(ex.Stub, "<HTML body omitted:"):
299			if m := htmlTitle.FindStringSubmatch(ex.Stub); m != nil {
300				return []byte("<html><head>" + m[1] + "</head></html>"), true
301			}
302		}
303		return nil, false
304	}
305	
306	func contains(list []string, s string) bool {
307		for _, v := range list {
308			if v == s {
309				return true
310			}
311		}
312		return false
313	}
