48	// bearerFlow is the three exchanges an anonymous client records against a
49	// registry that challenges it: the 401, the token, the retry with the token.
50	func bearerFlow(name string, id nexusfixture.Identity) nexusfixture.Fixture {
51		first := auth("")
52		if id != nexusfixture.Anonymous {
53			first = auth("Basic <redacted>")
54		}
55		return nexusfixture.Fixture{
56			Campaign: "synthetic", Name: name, Scenario: strings.TrimSuffix(name, "--"+string(id)), Identity: id,
57			Meta: nexusfixture.Meta{Flow: nexusfixture.FlowBearer},
58			Exchanges: []nexusfixture.Exchange{
59				exchange("GET", catalogTarget, first, 401,
60					http.Header{"Www-Authenticate": {challenge}, "Content-Type": {jsonType}}, `{"errors":[{"code":"UNAUTHORIZED"}]}`),
61				exchange("GET", tokenTarget, first, 200,
62					http.Header{"Content-Type": {jsonType}}, `{"token":"<redacted>","expires_in":300}`),
