155	func (s *Server) handler(routes []route) http.Handler {
156		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
157			id, known := identify(r)
158			if known {
159				if rt, ok := match(routes, r.Method, r.URL.RequestURI(), id); ok {
160					s.replay(w, rt)
161					return
162				}
163			}
164			label := unknownCredentials
165			if known {
166				label = string(id)
167			}
168			s.t.Errorf("no recorded answer for %s %s as %s", r.Method, r.URL.RequestURI(), label)
169			http.Error(w, "no recorded answer", http.StatusNotImplemented)
170		})
171	}
