173	// identify reads the account a request authenticates as. known is false when the
174	// credentials are none of the bench's: that never matches a recording.
175	func identify(r *http.Request) (id nexusfixture.Identity, known bool) {
176		if r.Header.Get("Authorization") == "" {
177			return nexusfixture.Anonymous, true
178		}
179		user, pass, ok := r.BasicAuth()
180		if !ok || pass != Password {
181			return "", false
182		}
183		for _, id := range []nexusfixture.Identity{nexusfixture.Admin, nexusfixture.Pull} {
184			if user == User(id) {
185				return id, true
186			}
187		}
188		return "", false
189	}
