61				exchange("GET", tokenTarget, first, 200,
62					http.Header{"Content-Type": {jsonType}}, `{"token":"<redacted>","expires_in":300}`),
63				exchange("GET", catalogTarget, auth("Bearer <redacted>"), 200,
